content.content:
1	import {normalize, analyze, reportMarkdown, personaMarkdown} from './analysis.mjs';
2	import {demo, personas} from './content.mjs';
3	import {mascot, badgeIcon} from './illustrations.mjs';
4	import {analysisPayload, aiSection, selectionHtml, aiMarkdown, escape} from './ai.mjs';
5	
6	const $ = selector => document.querySelector(selector);
7	let data = normalize(demo);
8	let result = analyze(data);
9	let mode = 'demo';
10	let view = 'discover';
11	let feedback = {};
12	let selectedPersona = personas[0];
13	let lastFocus = null;
14	let toastTimer;
15	let aiEnabled = false;
16	let aiResult = null;
17	let aiBusy = false;
18	let revision = 0;
19	
20	const report = () => reportMarkdown(result, mode, feedback) + aiMarkdown(aiResult);
21	
22	function notify(message) {
23	  $('#toast').textContent = message;
24	  $('#toast').classList.add('visible');
25	  clearTimeout(toastTimer);
26	  toastTimer = setTimeout(() => $('#toast').classList.remove('visible'), 4500);
27	}
28	
29	function modal(title, body, wide = false) {
30	  lastFocus = document.activeElement;
31	  $('#modal').classList.toggle('wide', wide);
32	  $('#modal-body').innerHTML = '<h2 id="modal-title">' + title + '</h2>' + body;
33	  if (!$('#modal').open) $('#modal').showModal();
34	}
35	
36	function download(text, filename, type = 'text/markdown') {
37	  const url = URL.createObjectURL(new Blob([text], {type: type + ';charset=utf-8'}));
38	  const link = document.createElement('a');
39	  link.href = url; link.download = filename; link.click();
40	  setTimeout(() => URL.revokeObjectURL(url), 1000);
41	}
42	
43	function recordHtml(choice) {
44	  return '<article class="record"><div class="record-meta"><span>' + escape(choice.context.project_key || '프로젝트 미지정')
45	    + '</span><time>' + escape((choice.recorded_at || '').slice(0, 10)) + '</time></div>'
46	    + '<h3>' + escape(choice.question) + '</h3><p class="chosen">' + escape(choice.chosen) + '</p>'
47	    + '<blockquote>' + escape(choice.reason_quote) + '</blockquote><details><summary>출처와 적용한 기준</summary>'
48	    + '<p class="mono">' + escape(choice.id) + '<br>' + escape(choice.origin.source_ref) + '</p>'
49	    + '<p>조건: ' + escape(JSON.stringify(choice.context.conditions || [])) + '</p><p class="mono">'
50	    + escape(choice.source_refs.join(', ') || '참조한 기준 없음') + '</p></details></article>';
51	}
52	
53	function discover() {
54	  const quote = data.choices[0]?.reason_quote;
55	  const heading = result.choiceCount ? '선택이 쌓이면,<br>내가 조금 더 보여요.' : '나를 알아가는 이야기는<br>작은 선택에서 시작돼요.';
56	  const earned = result.badges.filter(b => b.earned).length;
57	  const cards = result.recurring.slice(0, 2).map((group, i) => '<button class="insight ' + (i ? 'peach' : 'mint')
58	    + '" data-action="evidence" data-index="' + i + '"><span class="insight-symbol">' + (i ? '✳' : '⌁')
59	    + '</span><span class="eyeline">' + group.choices.length + '개의 선택에 연결된 기준</span><h3>'
60	    + escape(group.criterion.statement) + '</h3><span class="card-link">어떤 기록에서 나왔을까요? <span>↗</span></span></button>').join('');
61	  return '<section class="hero"><div class="hero-copy"><span class="pill">나의 작은 발견 노트</span><h1>' + heading
62	    + '</h1><p>무엇을 골랐는지, 왜 그랬는지.<br>Avatar에 모인 기록에서 나의 이야기를 꺼내봐요.</p>'
63	    + '<div class="hero-actions"><button class="button ink" data-action="report">나의 리포트 펼치기 <span>↗</span></button>'
64	    + '<button class="text-button" data-action="records">기록 살펴보기</button></div>'
65	    + '<div class="facts"><span><b>' + result.choiceCount + '</b>개의 선택</span><span><b>' + result.projectCount
66	    + '</b>개의 프로젝트</span><span><b>' + result.current.length + '</b>개의 확인한 기준</span></div></div>'
67	    + '<div class="hero-art"><span class="spark spark-one">✳</span><span class="spark spark-two">✦</span>'
68	    + '<div class="orbit-note note-one">이유가 있는 선택</div><div class="orbit-note note-two">조금씩 알아가는 중</div>'
69	    + mascot('bunny') + '<div class="pet-caption">당신의 이야기를 모으고 있어요.</div></div></section>'
70	    + '<section class="discoveries"><div class="section-heading"><div><span class="small-label">기록에서 찾았어요</span><h2>자꾸 돌아오는 나의 기준</h2></div>'
71	    + '<span class="quiet">참조한 기준과 선택을 함께 봅니다.</span></div><div class="insights">' + (cards
72	      || '<div class="empty"><h3>아직 반복된 기준을 찾지 못했어요.</h3><p>선택이 같은 현재 기준을 두 번 이상 참조하면 여기에 모아드려요.</p><button class="button outline" data-action="import">기록 가져오기</button></div>')
73	    + '</div><div class="two-notes"><button class="note-card" data-action="compare"><span class="note-icon">⇄</span><div><h3>같은 기준, 달랐던 선택</h3><p>'
74	    + result.comparisons.length + '쌍의 기록을 당시 상황과 함께 돌아봐요.</p></div><span>↗</span></button>'
75	    + '<button class="note-card" data-action="changes"><span class="note-icon">◒</span><div><h3>생각도 자라고 있어요</h3><p>'
76	    + result.revisions.length + '개의 기준에서 문장이 바뀐 이력을 찾았어요.</p></div><span>↗</span></button></div></section>'
77	    + aiSection(aiResult, aiBusy, result.choiceCount)
78	    + '<section class="collection"><div class="section-heading"><div><span class="small-label">작은 발견을 모아요</span><h2>나의 배지 서랍 <span class="count">'
79	    + earned + ' / 4</span></h2></div><p class="quiet">지금 불러온 기록으로 얻은 배지예요.</p></div><div class="badge-row">'
80	    + result.badges.map((b, i) => '<button class="badge-card ' + (b.earned ? 'earned' : 'locked')
81	      + '" data-action="badge" data-index="' + i + '"><span class="badge-shape shape-' + i + '">'
82	      + badgeIcon(b.icon) + '</span><b>' + b.name + '</b><span>' + (b.earned ? '발견했어요' : '아직 기다리는 중') + '</span></button>').join('')
83	    + '</div></section><section class="persona-invite"><div><span class="pill">다음의 나는 어떨까요?</span><h2>닮고 싶은 방식을<br>하나 골라볼까요?</h2>'
84	    + '<p>공개된 개발 원칙을 작은 캐릭터로 만나요.<br>마음에 드는 습관은 AI와 함께 써볼 수 있어요.</p>'
85	    + '<button class="button ink" data-action="personas">작업 방식 만나보기 <span>↗</span></button></div><div class="mini-friends">'
86	    + mascot('frog') + mascot('bear') + '</div></section>'
87	    + (quote ? '<section class="closing-quote"><span>기록 속, 당신이 남긴 한 문장</span><blockquote>“' + escape(quote) + '”</blockquote>'
88	      + '<small>' + (mode === 'demo' ? '설명용으로 만든 예시 문장입니다.' : '불러온 선택 기록의 이유 원문입니다.') + '</small></section>' : '')
89	    + '<p class="method-note">기록 요약과 AI 해석을 구분해서 보여드립니다. 심리검사 점수나 성격 진단은 제공하지 않습니다.</p>';
90	}
91	
92	function records() {
93	  return '<section class="page-intro"><span class="pill">어떤 순간의 나였나요?</span><h1>선택에는 이유가 있어요.</h1>'
94	    + '<p>기록의 원문과 그때의 조건을 함께 살펴보세요. 원본 기록은 여기서 바뀌지 않아요.</p></section>'
95	    + '<div class="record-tools"><label>기록 찾기<input id="search" type="search" placeholder="선택, 이유, 프로젝트로 검색"></label>'
96	    + '<button class="button outline" data-action="import">다른 기록 가져오기</button></div><div id="record-list" class="record-list">'
97	    + (data.choices.map(recordHtml).join('') || '<p class="empty">아직 불러온 선택이 없어요.</p>')
98	    + '</div><section class="criteria-section"><h2>기준의 현재와 이전 모습</h2>'
99	    + data.criteria.map(c => '<details class="criterion"><summary>'
100	      + escape(c.versions.find(v => v.version === c.current_version).statement)
101	      + '<span class="tag">' + (c.revoked ? '철회함' : c.versions.find(v => v.version === c.current_version).confirmation === 'user_confirmed' ? '불러온 시점에 확인됨' : '아직 제안') + '</span></summary>'
102	      + c.versions.map(v => '<div class="version"><b>' + escape(v.ref) + '</b><p>' + escape(v.statement)
103	        + '</p><small>' + escape(v.reason || '이유 기록 없음') + ' · ' + (v.confirmation === 'user_confirmed' ? '확인함' : '제안') + '</small></div>').join('')
104	      + '</details>').join('') + '<p class="quiet">첨부한 외부 이력 ' + data.projections.length
105	      + '개는 이 분석에서 현재 기준으로 사용하지 않아요. 기준을 적용할 때는 원본 Avatar에서 다시 확인하세요.</p></section>';
106	}
107	
108	function personaPage() {
109	  return '<section class="page-intro"><span class="pill">닮고 싶은 나를 향해</span><h1>이번에는, 이런 방식 어때요?</h1>'
110	    + '<p>마음에 드는 작업 습관을 골라 AI와 함께 써보세요.<br>기록으로 알아본 지금의 나와, 시도해볼 방식은 따로 남겨요.</p></section>'
111	    + '<div class="persona-grid">' + personas.map((p, i) => '<article class="persona-card ' + p.color + '"><div class="persona-art">'
112	      + mascot(p.kind) + '</div><div class="persona-copy"><span class="small-label">' + p.label + '</span><h2>' + p.name + '</h2><p>' + p.summary
113	      + '</p><ul>' + p.practices.map(rule => '<li>' + rule + '</li>').join('') + '</ul><a href="' + p.source
114	      + '" target="_blank" rel="noopener noreferrer">' + p.author + ' · ' + p.article + ' ↗</a>'
115	      + '<button class="button ink" data-action="persona" data-index="' + i + '">이 방식 써보기</button></div></article>').join('')
116	    + '</div><p class="method-note">Avatar가 공개 글을 바탕으로 정리한 예시입니다. 해당 인물이 직접 제공하거나 인증한 AI 설정은 아닙니다. 선택해도 기존 기준과 프로젝트 파일은 바뀌지 않아요.</p>';
117	}
118	
119	function render() {
120	  $('#main').innerHTML = view === 'records' ? records() : view === 'personas' ? personaPage() : discover();
121	  for (const nav of document.querySelectorAll('.nav')) {
122	    nav.classList.toggle('active', nav.dataset.view === view);
123	    if (nav.dataset.view === view) nav.setAttribute('aria-current', 'page');
124	    else nav.removeAttribute('aria-current');
125	  }
126	  $('#source-label').textContent = mode === 'demo' ? '예시 기록으로 둘러보고 있어요. 실제 사용자 기록이 아닙니다.'
127	    : mode === 'empty' ? '기록을 지웠어요. 새 기록을 가져올 수 있어요.'
128	      : '직접 불러온 기록이에요. AI 분석을 요청할 때만 고른 내용을 Claude로 보내요.';
129	  $('#source-switch').textContent = mode === 'demo' ? '내 기록으로 바꾸기' : '기록 바꾸기';
130	}
131	
132	function navigate(next) {
133	  view = next; render(); window.scrollTo({top: 0, behavior: 'instant'});
134	}
135	
136	function importDialog() {
137	  modal('나의 기록을 가져와요', '<p>Avatar에 쌓인 선택과 기준을 불러옵니다. 지금 화면의 기록을 새 기록으로 바꿔요.</p>'
138	    + '<div class="import-option"><h3>JSON 파일로 가져오기</h3><p>Avatar에서 아래 명령으로 저장한 파일을 골라주세요.</p>'
139	    + '<pre>python3 avatar/scripts/avatar.py show --json &gt; avatar-records.json</pre>'
140	    + '<button class="button ink" data-action="file">파일 고르기</button></div>'
141	    + '<div class="import-option"><h3>이 컴퓨터의 Avatar 연결</h3><p>뷰어를 실행할 때 <code>--home</code>으로 지정한 저장소만 읽어요.</p>'
142	    + '<button class="button outline" data-action="local">연결한 로컬 기록 읽기</button></div>'
143	    + '<p class="quiet">가져온 파일은 이 브라우저 탭에서만 읽습니다. 새로고침하거나 탭을 닫으면 가져온 기록과 메모가 사라집니다.</p>'
144	    + '<button class="text-button" data-action="demo">예시 기록으로 둘러보기</button>');
145	}
146	
147	function load(input, source) {
148	  const next = normalize(input);
149	  const nextResult = analyze(next);
150	  data = next; result = nextResult; mode = source; feedback = {};
151	  aiResult = null; revision++;
152	  $('#modal').close(); navigate('discover');
153	  notify(source === 'demo' ? '예시 기록을 불러왔어요.' : '기록을 불러왔어요. 원본은 바꾸지 않았어요.');
154	}
155	
156	function showReport() {
157	  modal('나의 발견 리포트', '<span class="pill">' + (mode === 'demo' ? '예시 기록' : '불러온 기록') + '</span>'
158	    + '<p>기록의 근거와 내가 덧붙인 생각을 함께 간직하세요.</p><div class="report-summary"><b>' + result.choiceCount
159	    + '</b><span>개의 선택</span><b>' + result.recurring.length + '</b><span>개의 반복해서 참조한 기준</span></div>'
160	    + '<pre class="report-preview">' + escape(report()) + '</pre>'
161	    + '<button class="button ink" data-action="report-download">리포트 내려받기</button>'
162	    + '<p class="quiet">현재 체험 버전에서는 무료입니다. 유료 분석과 결제는 아직 연결하지 않았어요.</p>', true);
163	}
164	
165	function updateSelection() {
166	  if (!$('#ai-start')) return;
167	  try {
168	    const payload = analysisPayload(data, [...document.querySelectorAll('[name="ai-choice"]:checked')].map(el => el.value));
169	    $('#ai-payload').textContent = JSON.stringify(payload, null, 2);
170	    $('#ai-start').disabled = !$('#ai-consent').checked;
171	  } catch (error) {
172	    $('#ai-payload').textContent = error.message;
173	    $('#ai-start').disabled = true;
174	  }
175	}
176	
177	async function startAnalysis() {
178	  if (aiBusy || !$('#ai-consent')?.checked) return;
179	  const payload = analysisPayload(data, [...document.querySelectorAll('[name="ai-choice"]:checked')].map(el => el.value));
180	  const sourceRevision = revision;
181	  aiBusy = true; $('#modal').close(); render();
182	  notify('고른 기록을 Claude가 읽고 있어요. 잠시만 기다려주세요.');
183	  try {
184	    const response = await fetch('/api/analyze', {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify(payload)});
185	    const output = await response.json();
186	    if (!response.ok) throw new Error(output.error || '분석을 마치지 못했어요. 다시 시도해주세요.');
187	    if (sourceRevision !== revision) return;
188	    aiResult = {...output, selected_ids: payload.choices.map(c => c.id), analyzed_at: new Date().toLocaleString('ko-KR')};
189	    notify('분석을 마쳤어요. 각 해석의 근거를 함께 살펴보세요.');
190	  } catch (error) {
191	    if (sourceRevision === revision) notify(error.message);
192	  } finally {
193	    aiBusy = false; render();
194	    if (sourceRevision === revision && view === 'discover') $('.ai-section')?.scrollIntoView({block: 'start'});
195	  }
196	}
197	
198	function showPersona(index) {
199	  selectedPersona = personas[index];
200	  modal(selectedPersona.name + ' · AI와 써보기', '<p>새로 시도할 작업 방식입니다. 기존의 나를 분석한 결과와 구분해요.</p>'
201	    + '<label class="field">어디에 써볼까요?<input id="persona-scope" value="이번 프로젝트의 다음 작업" maxlength="200"></label>'
202	    + '<label class="check-label"><input type="checkbox" id="persona-consent">규칙을 읽었고, 적은 범위에서 써보고 싶어요.</label>'
203	    + '<pre class="rules-preview" id="rules-preview">' + escape(personaMarkdown(selectedPersona, '이번 프로젝트의 다음 작업')) + '</pre>'
204	    + '<button class="button ink" id="persona-download" data-action="persona-download" disabled>AI 규칙 내려받기</button>'
205	    + '<p class="quiet">내려받은 문서를 Claude·Codex의 작업 대화에 첨부해 적용 범위를 알려주세요. 자동 적용하거나 프로젝트 파일을 덮어쓰지는 않아요.</p>', true);
206	}
207	
208	document.addEventListener('click', async event => {
209	  const button = event.target.closest('button');
210	  if (!button) return;
211	  if (button.dataset.view) { navigate(button.dataset.view); return; }
212	  const action = button.dataset.action;
213	  const index = Number(button.dataset.index);
214	  if (['records', 'personas', 'discover'].includes(action)) { navigate(action); return; }
215	  if (action === 'import' || ['import-open', 'source-switch'].includes(button.id)) importDialog();
216	  if (action === 'file') $('#file').click();
217	  if (action === 'demo') load(demo, 'demo');
218	  if (action === 'local') {
219	    button.disabled = true;
220	    try {
221	      const response = await fetch('/api/records');
222	      if (!response.ok) throw new Error('로컬 기록을 읽지 못했어요. --home으로 저장소를 지정하거나 JSON 파일을 가져와주세요.');
223	      load(await response.json(), 'local');
224	    } catch (error) { notify(error.message); } finally { button.disabled = false; }
225	  }
226	  if (action === 'report') showReport();
227	  if (action === 'report-download') { download(report(), 'avatar-report.md'); notify('리포트를 내려받았어요.'); }
228	  if (action === 'ai-select') { modal('함께 돌아볼 기록을 골라요', selectionHtml(data, mode, aiEnabled), true); updateSelection(); }
229	  if (action === 'ai-start') await startAnalysis();
230	  if (action === 'ai-evidence') {
231	    const insight = aiResult.insights[index];
232	    modal(escape(insight.title), '<p>' + escape(insight.interpretation) + '</p>'
233	      + data.choices.filter(c => insight.evidence_ids.includes(c.id)).map(recordHtml).join(''), true);
234	  }
235	  if (action === 'ai-note') modal('이 해석은 나에게 어떤가요?', '<p>잘 짚은 부분과 다르게 느끼는 부분을 적어주세요.</p>'
236	    + '<label class="field">리포트에 남길 나의 생각<textarea id="ai-note">' + escape(feedback.ai || '')
237	    + '</textarea></label><button class="button ink" data-action="ai-note-save">리포트에 더하기</button>');
238	  if (action === 'ai-note-save') { feedback.ai = $('#ai-note').value.slice(0, 3000); $('#modal').close(); notify('리포트에 내 생각을 더했어요.'); }
239	  if (action === 'evidence') {
240	    const group = result.recurring[index];
241	    modal('이 기준으로 이어진 선택들', '<p class="dialog-lead">' + escape(group.criterion.statement)
