244	      + index + '" placeholder="맞는 부분, 다른 부분, 그때의 사정을 남겨보세요.">'
245	      + escape(feedback[group.criterion.ref] || '') + '</textarea></label><button class="button ink" data-action="reflection-save" data-index="'
246	      + index + '">리포트에 내 생각 더하기</button><p class="quiet">메모는 이 탭에만 남습니다. 간직하려면 리포트를 내려받으세요. 원본 기준은 바뀌지 않아요.</p>', true);
247	  }
