249	    feedback[result.recurring[index].criterion.ref] = $('#reflection').value.slice(0, 3000);
250	    $('#modal').close(); notify('리포트에 내 생각을 더했어요.');
251	  }
252	  if (action === 'compare') modal('선택이 달랐던 순간', result.comparisons.length
253	    ? result.comparisons.map(pair => '<section class="comparison"><p class="pill">'
254	      + (pair.conditions_differ ? '상황이 달랐어요' : '이유를 함께 살펴봐요') + '</p>'
255	      + pair.choices.map(recordHtml).join('') + '</section>').join('')
256	    : '<p>같은 기준을 참조하면서 다르게 고른 기록은 아직 없어요.</p>', true);
257	  if (action === 'changes') modal('생각이 바뀐 흔적', result.revisions.length
258	    ? result.revisions.map(c => '<section class="timeline">' + c.versions.map(v => '<div class="version"><small>'
259	      + escape(v.ref) + ' · ' + (v.confirmation === 'user_confirmed' ? '확인함' : '제안') + '</small><h3>'
260	      + escape(v.statement) + '</h3><p>' + escape(v.reason || '이유 기록 없음') + '</p></div>').join('') + '</section>').join('')
261	    : '<p>기준의 문장이 바뀐 기록은 아직 없어요.</p>', true);
262	  if (action === 'badge') {
263	    const badge = result.badges[index];
264	    modal(badge.name, '<div class="badge-large">' + badgeIcon(badge.icon) + '</div><p class="dialog-lead">'
265	      + (badge.earned ? badge.detail : '이 배지는 아직 기다리는 중이에요. ' + badge.detail)
266	      + '</p><p class="quiet">불러온 기록으로 확인한 배지예요. 성격의 점수나 다른 사람과의 순위는 아닙니다.</p>');
267	  }
268	  if (action === 'persona') showPersona(index);
269	  if (action === 'persona-download' && $('#persona-consent').checked) {
270	    try { download(personaMarkdown(selectedPersona, $('#persona-scope').value), 'avatar-working-style.md');
271	      notify('선택한 규칙을 내려받았어요. 아직 AI에 적용되지는 않았어요.'); }
272	    catch (error) { notify(error.message); }
273	  }
274	  if (button.id === 'modal-close') $('#modal').close();
275	  if (button.id === 'clear') {
276	    data = normalize({choices: [], criteria: []}); result = analyze(data); mode = 'empty'; feedback = {};
277	    aiResult = null; revision++;
278	    navigate('discover'); notify('이 탭에서 불러온 기록을 지웠어요. 원본은 그대로예요.');
