284	  if (event.target.id === 'search') {
285	    const text = event.target.value.toLocaleLowerCase();
286	    const matched = data.choices.filter(c => [c.question, c.chosen, c.reason_quote, c.context.project_key]
287	      .some(s => s.toLocaleLowerCase().includes(text)));
288	    $('#record-list').innerHTML = matched.map(recordHtml).join('') || '<p class="empty">일치하는 기록이 없어요.</p>';
