import {normalize, analyze, reportMarkdown, personaMarkdown} from './analysis.mjs';
import {demo, personas} from './content.mjs';
import {mascot, badgeIcon} from './illustrations.mjs';
import {analysisPayload, aiSection, selectionHtml, aiMarkdown, escape} from './ai.mjs';

const $ = selector => document.querySelector(selector);
let data = normalize(demo);
let result = analyze(data);
let mode = 'demo';
let view = 'discover';
let feedback = {};
let selectedPersona = personas[0];
let lastFocus = null;
let toastTimer;
let aiEnabled = false;
let aiResult = null;
let aiBusy = false;
let revision = 0;

const report = () => reportMarkdown(result, mode, feedback) + aiMarkdown(aiResult);

function notify(message) {
  $('#toast').textContent = message;
  $('#toast').classList.add('visible');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => $('#toast').classList.remove('visible'), 4500);
}

function modal(title, body, wide = false) {
  lastFocus = document.activeElement;
  $('#modal').classList.toggle('wide', wide);
  $('#modal-body').innerHTML = '<h2 id="modal-title">' + title + '</h2>' + body;
  if (!$('#modal').open) $('#modal').showModal();
}

function download(text, filename, type = 'text/markdown') {
  const url = URL.createObjectURL(new Blob([text], {type: type + ';charset=utf-8'}));
  const link = document.createElement('a');
  link.href = url; link.download = filename; link.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function recordHtml(choice) {
  return '<article class="record"><div class="record-meta"><span>' + escape(choice.context.project_key || '프로젝트 미지정')
    + '</span><time>' + escape((choice.recorded_at || '').slice(0, 10)) + '</time></div>'
    + '<h3>' + escape(choice.question) + '</h3><p class="chosen">' + escape(choice.chosen) + '</p>'
    + '<blockquote>' + escape(choice.reason_quote) + '</blockquote><details><summary>출처와 적용한 기준</summary>'
    + '<p class="mono">' + escape(choice.id) + '<br>' + escape(choice.origin.source_ref) + '</p>'
    + '<p>조건: ' + escape(JSON.stringify(choice.context.conditions || [])) + '</p><p class="mono">'
    + escape(choice.source_refs.join(', ') || '참조한 기준 없음') + '</p></details></article>';
}

function discover() {
  const quote = data.choices[0]?.reason_quote;
  const heading = result.choiceCount ? '선택이 쌓이면,<br>내가 조금 더 보여요.' : '나를 알아가는 이야기는<br>작은 선택에서 시작돼요.';
  const earned = result.badges.filter(b => b.earned).length;
  const cards = result.recurring.slice(0, 2).map((group, i) => '<button class="insight ' + (i ? 'peach' : 'mint')
    + '" data-action="evidence" data-index="' + i + '"><span class="insight-symbol">' + (i ? '✳' : '⌁')
    + '</span><span class="eyeline">' + group.choices.length + '개의 선택에 연결된 기준</span><h3>'
    + escape(group.criterion.statement) + '</h3><span class="card-link">어떤 기록에서 나왔을까요? <span>↗</span></span></button>').join('');
  return '<section class="hero"><div class="hero-copy"><span class="pill">나의 작은 발견 노트</span><h1>' + heading
    + '</h1><p>무엇을 골랐는지, 왜 그랬는지.<br>Avatar에 모인 기록에서 나의 이야기를 꺼내봐요.</p>'
    + '<div class="hero-actions"><button class="button ink" data-action="report">나의 리포트 펼치기 <span>↗</span></button>'
    + '<button class="text-button" data-action="records">기록 살펴보기</button></div>'
    + '<div class="facts"><span><b>' + result.choiceCount + '</b>개의 선택</span><span><b>' + result.projectCount
    + '</b>개의 프로젝트</span><span><b>' + result.current.length + '</b>개의 확인한 기준</span></div></div>'
    + '<div class="hero-art"><span class="spark spark-one">✳</span><span class="spark spark-two">✦</span>'
    + '<div class="orbit-note note-one">이유가 있는 선택</div><div class="orbit-note note-two">조금씩 알아가는 중</div>'
    + mascot('bunny') + '<div class="pet-caption">당신의 이야기를 모으고 있어요.</div></div></section>'
    + '<section class="discoveries"><div class="section-heading"><div><span class="small-label">기록에서 찾았어요</span><h2>자꾸 돌아오는 나의 기준</h2></div>'
    + '<span class="quiet">참조한 기준과 선택을 함께 봅니다.</span></div><div class="insights">' + (cards
      || '<div class="empty"><h3>아직 반복된 기준을 찾지 못했어요.</h3><p>선택이 같은 현재 기준을 두 번 이상 참조하면 여기에 모아드려요.</p><button class="button outline" data-action="import">기록 가져오기</button></div>')
    + '</div><div class="two-notes"><button class="note-card" data-action="compare"><span class="note-icon">⇄</span><div><h3>같은 기준, 달랐던 선택</h3><p>'
    + result.comparisons.length + '쌍의 기록을 당시 상황과 함께 돌아봐요.</p></div><span>↗</span></button>'
    + '<button class="note-card" data-action="changes"><span class="note-icon">◒</span><div><h3>생각도 자라고 있어요</h3><p>'
    + result.revisions.length + '개의 기준에서 문장이 바뀐 이력을 찾았어요.</p></div><span>↗</span></button></div></section>'
    + aiSection(aiResult, aiBusy, result.choiceCount)
    + '<section class="collection"><div class="section-heading"><div><span class="small-label">작은 발견을 모아요</span><h2>나의 배지 서랍 <span class="count">'
    + earned + ' / 4</span></h2></div><p class="quiet">지금 불러온 기록으로 얻은 배지예요.</p></div><div class="badge-row">'
    + result.badges.map((b, i) => '<button class="badge-card ' + (b.earned ? 'earned' : 'locked')
      + '" data-action="badge" data-index="' + i + '"><span class="badge-shape shape-' + i + '">'
      + badgeIcon(b.icon) + '</span><b>' + b.name + '</b><span>' + (b.earned ? '발견했어요' : '아직 기다리는 중') + '</span></button>').join('')
    + '</div></section><section class="persona-invite"><div><span class="pill">다음의 나는 어떨까요?</span><h2>닮고 싶은 방식을<br>하나 골라볼까요?</h2>'
    + '<p>공개된 개발 원칙을 작은 캐릭터로 만나요.<br>마음에 드는 습관은 AI와 함께 써볼 수 있어요.</p>'
    + '<button class="button ink" data-action="personas">작업 방식 만나보기 <span>↗</span></button></div><div class="mini-friends">'
    + mascot('frog') + mascot('bear') + '</div></section>'
    + (quote ? '<section class="closing-quote"><span>기록 속, 당신이 남긴 한 문장</span><blockquote>“' + escape(quote) + '”</blockquote>'
      + '<small>' + (mode === 'demo' ? '설명용으로 만든 예시 문장입니다.' : '불러온 선택 기록의 이유 원문입니다.') + '</small></section>' : '')
    + '<p class="method-note">기록 요약과 AI 해석을 구분해서 보여드립니다. 심리검사 점수나 성격 진단은 제공하지 않습니다.</p>';
}

function records() {
  return '<section class="page-intro"><span class="pill">어떤 순간의 나였나요?</span><h1>선택에는 이유가 있어요.</h1>'
    + '<p>기록의 원문과 그때의 조건을 함께 살펴보세요. 원본 기록은 여기서 바뀌지 않아요.</p></section>'
    + '<div class="record-tools"><label>기록 찾기<input id="search" type="search" placeholder="선택, 이유, 프로젝트로 검색"></label>'
    + '<button class="button outline" data-action="import">다른 기록 가져오기</button></div><div id="record-list" class="record-list">'
    + (data.choices.map(recordHtml).join('') || '<p class="empty">아직 불러온 선택이 없어요.</p>')
    + '</div><section class="criteria-section"><h2>기준의 현재와 이전 모습</h2>'
    + data.criteria.map(c => '<details class="criterion"><summary>'
      + escape(c.versions.find(v => v.version === c.current_version).statement)
      + '<span class="tag">' + (c.revoked ? '철회함' : c.versions.find(v => v.version === c.current_version).confirmation === 'user_confirmed' ? '불러온 시점에 확인됨' : '아직 제안') + '</span></summary>'
      + c.versions.map(v => '<div class="version"><b>' + escape(v.ref) + '</b><p>' + escape(v.statement)
        + '</p><small>' + escape(v.reason || '이유 기록 없음') + ' · ' + (v.confirmation === 'user_confirmed' ? '확인함' : '제안') + '</small></div>').join('')
      + '</details>').join('') + '<p class="quiet">첨부한 외부 이력 ' + data.projections.length
      + '개는 이 분석에서 현재 기준으로 사용하지 않아요. 기준을 적용할 때는 원본 Avatar에서 다시 확인하세요.</p></section>';
}

function personaPage() {
  return '<section class="page-intro"><span class="pill">닮고 싶은 나를 향해</span><h1>이번에는, 이런 방식 어때요?</h1>'
    + '<p>마음에 드는 작업 습관을 골라 AI와 함께 써보세요.<br>기록으로 알아본 지금의 나와, 시도해볼 방식은 따로 남겨요.</p></section>'
    + '<div class="persona-grid">' + personas.map((p, i) => '<article class="persona-card ' + p.color + '"><div class="persona-art">'
      + mascot(p.kind) + '</div><div class="persona-copy"><span class="small-label">' + p.label + '</span><h2>' + p.name + '</h2><p>' + p.summary
      + '</p><ul>' + p.practices.map(rule => '<li>' + rule + '</li>').join('') + '</ul><a href="' + p.source
      + '" target="_blank" rel="noopener noreferrer">' + p.author + ' · ' + p.article + ' ↗</a>'
      + '<button class="button ink" data-action="persona" data-index="' + i + '">이 방식 써보기</button></div></article>').join('')
    + '</div><p class="method-note">Avatar가 공개 글을 바탕으로 정리한 예시입니다. 해당 인물이 직접 제공하거나 인증한 AI 설정은 아닙니다. 선택해도 기존 기준과 프로젝트 파일은 바뀌지 않아요.</p>';
}

function render() {
  $('#main').innerHTML = view === 'records' ? records() : view === 'personas' ? personaPage() : discover();
  for (const nav of document.querySelectorAll('.nav')) {
    nav.classList.toggle('active', nav.dataset.view === view);
    if (nav.dataset.view === view) nav.setAttribute('aria-current', 'page');
    else nav.removeAttribute('aria-current');
  }
  $('#source-label').textContent = mode === 'demo' ? '예시 기록으로 둘러보고 있어요. 실제 사용자 기록이 아닙니다.'
    : mode === 'empty' ? '기록을 지웠어요. 새 기록을 가져올 수 있어요.'
      : '직접 불러온 기록이에요. AI 분석을 요청할 때만 고른 내용을 Claude로 보내요.';
  $('#source-switch').textContent = mode === 'demo' ? '내 기록으로 바꾸기' : '기록 바꾸기';
}

function navigate(next) {
  view = next; render(); window.scrollTo({top: 0, behavior: 'instant'});
}

function importDialog() {
  modal('나의 기록을 가져와요', '<p>Avatar에 쌓인 선택과 기준을 불러옵니다. 지금 화면의 기록을 새 기록으로 바꿔요.</p>'
    + '<div class="import-option"><h3>JSON 파일로 가져오기</h3><p>Avatar에서 아래 명령으로 저장한 파일을 골라주세요.</p>'
    + '<pre>python3 avatar/scripts/avatar.py show --json &gt; avatar-records.json</pre>'
    + '<button class="button ink" data-action="file">파일 고르기</button></div>'
    + '<div class="import-option"><h3>이 컴퓨터의 Avatar 연결</h3><p>뷰어를 실행할 때 <code>--home</code>으로 지정한 저장소만 읽어요.</p>'
    + '<button class="button outline" data-action="local">연결한 로컬 기록 읽기</button></div>'
    + '<p class="quiet">가져온 파일은 이 브라우저 탭에서만 읽습니다. 새로고침하거나 탭을 닫으면 가져온 기록과 메모가 사라집니다.</p>'
    + '<button class="text-button" data-action="demo">예시 기록으로 둘러보기</button>');
}

function load(input, source) {
  const next = normalize(input);
  const nextResult = analyze(next);
  data = next; result = nextResult; mode = source; feedback = {};
  aiResult = null; revision++;
  $('#modal').close(); navigate('discover');
  notify(source === 'demo' ? '예시 기록을 불러왔어요.' : '기록을 불러왔어요. 원본은 바꾸지 않았어요.');
}

function showReport() {
  modal('나의 발견 리포트', '<span class="pill">' + (mode === 'demo' ? '예시 기록' : '불러온 기록') + '</span>'
    + '<p>기록의 근거와 내가 덧붙인 생각을 함께 간직하세요.</p><div class="report-summary"><b>' + result.choiceCount
    + '</b><span>개의 선택</span><b>' + result.recurring.length + '</b><span>개의 반복해서 참조한 기준</span></div>'
    + '<pre class="report-preview">' + escape(report()) + '</pre>'
    + '<button class="button ink" data-action="report-download">리포트 내려받기</button>'
    + '<p class="quiet">현재 체험 버전에서는 무료입니다. 유료 분석과 결제는 아직 연결하지 않았어요.</p>', true);
}

function updateSelection() {
  if (!$('#ai-start')) return;
  try {
    const payload = analysisPayload(data, [...document.querySelectorAll('[name="ai-choice"]:checked')].map(el => el.value));
    $('#ai-payload').textContent = JSON.stringify(payload, null, 2);
    $('#ai-start').disabled = !$('#ai-consent').checked;
  } catch (error) {
    $('#ai-payload').textContent = error.message;
    $('#ai-start').disabled = true;
  }
}

async function startAnalysis() {
  if (aiBusy || !$('#ai-consent')?.checked) return;
  const payload = analysisPayload(data, [...document.querySelectorAll('[name="ai-choice"]:checked')].map(el => el.value));
  const sourceRevision = revision;
  aiBusy = true; $('#modal').close(); render();
  notify('고른 기록을 Claude가 읽고 있어요. 잠시만 기다려주세요.');
  try {
    const response = await fetch('/api/analyze', {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify(payload)});
    const output = await response.json();
    if (!response.ok) throw new Error(output.error || '분석을 마치지 못했어요. 다시 시도해주세요.');
    if (sourceRevision !== revision) return;
    aiResult = {...output, selected_ids: payload.choices.map(c => c.id), analyzed_at: new Date().toLocaleString('ko-KR')};
    notify('분석을 마쳤어요. 각 해석의 근거를 함께 살펴보세요.');
  } catch (error) {
    if (sourceRevision === revision) notify(error.message);
  } finally {
    aiBusy = false; render();
    if (sourceRevision === revision && view === 'discover') $('.ai-section')?.scrollIntoView({block: 'start'});
  }
}

function showPersona(index) {
  selectedPersona = personas[index];
  modal(selectedPersona.name + ' · AI와 써보기', '<p>새로 시도할 작업 방식입니다. 기존의 나를 분석한 결과와 구분해요.</p>'
    + '<label class="field">어디에 써볼까요?<input id="persona-scope" value="이번 프로젝트의 다음 작업" maxlength="200"></label>'
    + '<label class="check-label"><input type="checkbox" id="persona-consent">규칙을 읽었고, 적은 범위에서 써보고 싶어요.</label>'
    + '<pre class="rules-preview" id="rules-preview">' + escape(personaMarkdown(selectedPersona, '이번 프로젝트의 다음 작업')) + '</pre>'
    + '<button class="button ink" id="persona-download" data-action="persona-download" disabled>AI 규칙 내려받기</button>'
    + '<p class="quiet">내려받은 문서를 Claude·Codex의 작업 대화에 첨부해 적용 범위를 알려주세요. 자동 적용하거나 프로젝트 파일을 덮어쓰지는 않아요.</p>', true);
}

document.addEventListener('click', async event => {
  const button = event.target.closest('button');
  if (!button) return;
  if (button.dataset.view) { navigate(button.dataset.view); return; }
  const action = button.dataset.action;
  const index = Number(button.dataset.index);
  if (['records', 'personas', 'discover'].includes(action)) { navigate(action); return; }
  if (action === 'import' || ['import-open', 'source-switch'].includes(button.id)) importDialog();
  if (action === 'file') $('#file').click();
  if (action === 'demo') load(demo, 'demo');
  if (action === 'local') {
    button.disabled = true;
    try {
      const response = await fetch('/api/records');
      if (!response.ok) throw new Error('로컬 기록을 읽지 못했어요. --home으로 저장소를 지정하거나 JSON 파일을 가져와주세요.');
      load(await response.json(), 'local');
    } catch (error) { notify(error.message); } finally { button.disabled = false; }
  }
  if (action === 'report') showReport();
  if (action === 'report-download') { download(report(), 'avatar-report.md'); notify('리포트를 내려받았어요.'); }
  if (action === 'ai-select') { modal('함께 돌아볼 기록을 골라요', selectionHtml(data, mode, aiEnabled), true); updateSelection(); }
  if (action === 'ai-start') await startAnalysis();
  if (action === 'ai-evidence') {
    const insight = aiResult.insights[index];
    modal(escape(insight.title), '<p>' + escape(insight.interpretation) + '</p>'
      + data.choices.filter(c => insight.evidence_ids.includes(c.id)).map(recordHtml).join(''), true);
  }
  if (action === 'ai-note') modal('이 해석은 나에게 어떤가요?', '<p>잘 짚은 부분과 다르게 느끼는 부분을 적어주세요.</p>'
    + '<label class="field">리포트에 남길 나의 생각<textarea id="ai-note">' + escape(feedback.ai || '')
    + '</textarea></label><button class="button ink" data-action="ai-note-save">리포트에 더하기</button>');
  if (action === 'ai-note-save') { feedback.ai = $('#ai-note').value.slice(0, 3000); $('#modal').close(); notify('리포트에 내 생각을 더했어요.'); }
  if (action === 'evidence') {
    const group = result.recurring[index];
    modal('이 기준으로 이어진 선택들', '<p class="dialog-lead">' + escape(group.criterion.statement)
      + '</p><p class="quiet">선택들이 이 기준을 참조했습니다. 선택마다 기준을 잘 따랐는지는 이유와 상황을 함께 살펴보세요.</p>'
      + group.choices.map(recordHtml).join('') + '<label class="field">지금 보니 어떤 생각이 드나요?<textarea id="reflection" data-ref="'
      + index + '" placeholder="맞는 부분, 다른 부분, 그때의 사정을 남겨보세요.">'
      + escape(feedback[group.criterion.ref] || '') + '</textarea></label><button class="button ink" data-action="reflection-save" data-index="'
      + index + '">리포트에 내 생각 더하기</button><p class="quiet">메모는 이 탭에만 남습니다. 간직하려면 리포트를 내려받으세요. 원본 기준은 바뀌지 않아요.</p>', true);
  }
  if (action === 'reflection-save') {
    feedback[result.recurring[index].criterion.ref] = $('#reflection').value.slice(0, 3000);
    $('#modal').close(); notify('리포트에 내 생각을 더했어요.');
  }
  if (action === 'compare') modal('선택이 달랐던 순간', result.comparisons.length
    ? result.comparisons.map(pair => '<section class="comparison"><p class="pill">'
      + (pair.conditions_differ ? '상황이 달랐어요' : '이유를 함께 살펴봐요') + '</p>'
      + pair.choices.map(recordHtml).join('') + '</section>').join('')
    : '<p>같은 기준을 참조하면서 다르게 고른 기록은 아직 없어요.</p>', true);
  if (action === 'changes') modal('생각이 바뀐 흔적', result.revisions.length
    ? result.revisions.map(c => '<section class="timeline">' + c.versions.map(v => '<div class="version"><small>'
      + escape(v.ref) + ' · ' + (v.confirmation === 'user_confirmed' ? '확인함' : '제안') + '</small><h3>'
      + escape(v.statement) + '</h3><p>' + escape(v.reason || '이유 기록 없음') + '</p></div>').join('') + '</section>').join('')
    : '<p>기준의 문장이 바뀐 기록은 아직 없어요.</p>', true);
  if (action === 'badge') {
    const badge = result.badges[index];
    modal(badge.name, '<div class="badge-large">' + badgeIcon(badge.icon) + '</div><p class="dialog-lead">'
      + (badge.earned ? badge.detail : '이 배지는 아직 기다리는 중이에요. ' + badge.detail)
      + '</p><p class="quiet">불러온 기록으로 확인한 배지예요. 성격의 점수나 다른 사람과의 순위는 아닙니다.</p>');
  }
  if (action === 'persona') showPersona(index);
  if (action === 'persona-download' && $('#persona-consent').checked) {
    try { download(personaMarkdown(selectedPersona, $('#persona-scope').value), 'avatar-working-style.md');
      notify('선택한 규칙을 내려받았어요. 아직 AI에 적용되지는 않았어요.'); }
    catch (error) { notify(error.message); }
  }
  if (button.id === 'modal-close') $('#modal').close();
  if (button.id === 'clear') {
    data = normalize({choices: [], criteria: []}); result = analyze(data); mode = 'empty'; feedback = {};
    aiResult = null; revision++;
    navigate('discover'); notify('이 탭에서 불러온 기록을 지웠어요. 원본은 그대로예요.');
  }
});

document.addEventListener('input', event => {
  if (event.target.name === 'ai-choice' || event.target.id === 'ai-consent') updateSelection();
  if (event.target.id === 'search') {
    const text = event.target.value.toLocaleLowerCase();
    const matched = data.choices.filter(c => [c.question, c.chosen, c.reason_quote, c.context.project_key]
      .some(s => s.toLocaleLowerCase().includes(text)));
    $('#record-list').innerHTML = matched.map(recordHtml).join('') || '<p class="empty">일치하는 기록이 없어요.</p>';
  }
  if (['persona-scope', 'persona-consent'].includes(event.target.id)) {
    const valid = $('#persona-scope').value.trim().length > 0;
    $('#persona-download').disabled = !valid || !$('#persona-consent').checked;
    if (valid) $('#rules-preview').textContent = personaMarkdown(selectedPersona, $('#persona-scope').value);
  }
});

$('#file').addEventListener('change', async event => {
  const file = event.target.files[0];
  if (!file) return;
  try {
    if (file.size > 8 * 1024 * 1024) throw new Error('파일은 8MB 이하로 가져와주세요.');
    load(JSON.parse(await file.text()), 'file');
  } catch (error) {
    notify(error instanceof SyntaxError ? 'JSON 파일을 읽지 못했어요. Avatar에서 다시 내보내주세요.' : error.message);
  } finally { event.target.value = ''; }
});
$('#modal').addEventListener('close', () => lastFocus?.isConnected && lastFocus.focus());
$('.wordmark').addEventListener('click', event => { event.preventDefault(); navigate('discover'); });
render();
fetch('/api/config').then(r => r.ok ? r.json() : {}).then(config => { aiEnabled = config.ai === true; }).catch(() => {});

