const LIMIT = 2000;
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const string = value => typeof value === 'string' && value.length <= 20000;
const required = value => string(value) && value.trim().length > 0;
const fail = () => { throw new Error('Avatar의 show --json 파일인지 확인해주세요. 기록 형식이 맞지 않습니다.'); };
const canonical = value => Array.isArray(value) ? value.map(canonical) : object(value)
  ? Object.fromEntries(Object.keys(value).sort().map(key => [key, canonical(value[key])])) : value;

export function normalize(input) {
  if (!object(input) || !Array.isArray(input.choices) || !Array.isArray(input.criteria)
      || input.choices.length > LIMIT || input.criteria.length > LIMIT) fail();
  const data = JSON.parse(JSON.stringify(input));
  const ids = new Set();
  for (const choice of data.choices) {
    if (!object(choice) || !['id', 'question', 'chosen', 'reason_quote'].every(k => required(choice[k]))
        || !object(choice.context) || !string(choice.context.project_key)
        || (choice.recorded_at !== undefined && !string(choice.recorded_at))
        || (choice.context.conditions !== undefined && !Array.isArray(choice.context.conditions))
        || !object(choice.origin) || !required(choice.origin.source_ref)
        || !Array.isArray(choice.source_refs) || !choice.source_refs.every(required)
        || !Array.isArray(choice.options) || !choice.options.every(string)
        || !choice.options.includes(choice.chosen) || ids.has(choice.id)) fail();
    ids.add(choice.id);
  }
  const criterionIds = new Set();
  for (const criterion of data.criteria) {
    if (!object(criterion) || !required(criterion.id) || criterionIds.has(criterion.id)
        || typeof criterion.revoked !== 'boolean' || !Number.isInteger(criterion.current_version)
        || !Array.isArray(criterion.versions) || !criterion.versions.length) fail();
    criterionIds.add(criterion.id);
    const versions = new Set();
    for (const v of criterion.versions) {
      if (!object(v) || !Number.isInteger(v.version) || v.version < 1 || versions.has(v.version)
          || v.ref !== 'avatar:' + criterion.id + '@' + v.version || !required(v.statement)
          || !['none', 'user_confirmed'].includes(v.confirmation)) fail();
      versions.add(v.version);
    }
    if (!versions.has(criterion.current_version)) fail();
    criterion.versions.sort((a, b) => a.version - b.version);
    criterion.events ??= [];
    if (!Array.isArray(criterion.events)) fail();
  }
  data.review_candidates ??= [];
  data.projections ??= [];
  if (!Array.isArray(data.projections) || !Array.isArray(data.review_candidates)
      || data.review_candidates.length > 100000) fail();
  for (const pair of data.review_candidates) {
    if (!object(pair) || !Array.isArray(pair.choice_ids) || pair.choice_ids.length !== 2
        || pair.choice_ids[0] === pair.choice_ids[1] || !pair.choice_ids.every(id => ids.has(id))) fail();
  }
  return data;
}

export function analyze(data) {
  const current = data.criteria.filter(c => !c.revoked).flatMap(c => c.versions
    .filter(v => v.version === c.current_version && v.confirmation === 'user_confirmed'));
  const recurring = current.map(criterion => ({criterion,
    choices: data.choices.filter(c => c.source_refs.includes(criterion.ref))}))
    .filter(group => group.choices.length >= 2).sort((a, b) => b.choices.length - a.choices.length);
  const revisions = data.criteria.filter(c => new Set(c.versions.map(v => v.statement)).size > 1);
  const byId = new Map(data.choices.map(c => [c.id, c]));
  const seen = new Set();
  const comparisons = data.review_candidates.flatMap(pair => {
    const choices = pair.choice_ids.map(id => byId.get(id));
    const key = [...pair.choice_ids].sort().join('|');
    const shared = choices[0].source_refs.filter(ref => choices[1].source_refs.includes(ref));
    if (seen.has(key) || !shared.length || choices[0].chosen === choices[1].chosen) return [];
    seen.add(key);
    return [{choices, source_refs: shared,
      conditions_differ: JSON.stringify(canonical(choices[0].context)) !== JSON.stringify(canonical(choices[1].context))}];
  });
  const projectCount = new Set(data.choices.map(c => c.context.project_key).filter(Boolean)).size;
  return {data, current, recurring, revisions, comparisons, projectCount,
    choiceCount: data.choices.length,
    badges: [
      {id: 'first', name: '이야기의 시작', detail: '첫 선택의 근거를 가져왔어요.',
        earned: data.choices.length > 0, icon: 'seed'},
      {id: 'thread', name: '이어지는 생각', detail: '같은 현재 기준을 참조한 선택이 두 개 이상 있어요.',
        earned: recurring.length > 0, icon: 'thread'},
      {id: 'change', name: '달라진 생각', detail: '기준의 문장이 바뀐 이력이 있어요.',
        earned: revisions.length > 0, icon: 'moon'},
      {id: 'worlds', name: '여러 곳의 나', detail: '서로 다른 프로젝트의 기록을 모았어요.',
        earned: projectCount >= 2, icon: 'world'},
    ]};
}

const line = value => String(value ?? '').replace(/[\r\n]+/g, ' ');
const quote = value => String(value ?? '').split('\n').map(x => '> ' + x).join('\n');

export function reportMarkdown(result, mode, feedback = {}) {
  const output = ['# Avatar · 기록 속의 나', '',
    mode === 'demo' ? '자료: 예시 기록입니다. 실제 사용자의 분석이 아닙니다.' : '자료: 사용자가 불러온 Avatar 기록입니다.',
    '이 문서는 불러온 시점의 기록 요약입니다. 성격 진단이나 실시간 기준 확인 결과가 아닙니다.', '',
    '선택 ' + result.choiceCount + '개 · 프로젝트 ' + result.projectCount + '개 · 확인한 현재 기준 '
      + result.current.length + '개', '', '## 반복해서 참조한 기준', ''];
  for (const group of result.recurring) {
    output.push('### ' + line(group.criterion.statement), '',
      '참조: ' + line(group.criterion.ref), '연결된 선택: ' + group.choices.length + '개', '');
    for (const c of group.choices) output.push('- ' + line(c.id) + ': ' + line(c.chosen),
      quote(c.reason_quote), '출처: ' + line(c.origin.source_ref), '');
  }
  if (!result.recurring.length) output.push('반복해서 참조한 현재 기준을 찾지 못했습니다.', '');
  output.push('## 바뀐 기준', '');
  for (const criterion of result.revisions) {
    output.push('### ' + line(criterion.id), '');
    for (const v of criterion.versions) output.push('- ' + line(v.ref) + ': ' + line(v.statement)
      + ' [' + line(v.confirmation) + ']', '이유: ' + line(v.reason || '기록되지 않음'));
  }
  output.push('', '## 나란히 볼 선택', '');
  for (const pair of result.comparisons) output.push(pair.choices.map(c => line(c.id) + ': '
    + line(c.chosen) + ' (' + line(c.context.project_key) + ')').join(' / '),
    pair.conditions_differ ? '상황이 다릅니다. 같은 기준으로 비교할 수 있는지 먼저 살펴보세요.'
      : '같은 기준을 참조했지만 선택은 달랐습니다. 당시 이유를 함께 살펴보세요.', '');
  output.push('## 내가 덧붙인 생각', '', ...Object.values(feedback).filter(Boolean).map(quote), '',
    '이 메모는 개인 기준의 확인이나 변경을 뜻하지 않습니다.', '', '## 선택 원문', '');
  for (const c of result.data.choices) output.push('### ' + line(c.question), '',
    '선택: ' + line(c.chosen), quote(c.reason_quote), '출처: ' + line(c.origin.source_ref),
    '프로젝트: ' + line(c.context.project_key), '기록: ' + line(c.recorded_at || '시점 없음'), '');
  return output.join('\n');
}

export function personaMarkdown(persona, scope) {
  if (!required(scope) || scope.length > 200) throw new Error('적용할 작업이나 프로젝트를 적어주세요.');
  return ['# Avatar working-style experiment', '',
    'Selected style: ' + line(persona.name), 'Scope: ' + line(scope), '',
    'This is a user-selected experiment, not an inferred or confirmed personal criterion.',
    'Use only within the scope above. Follow existing project instructions and the current user request.',
    'If a rule conflicts, explain the conflict and do not replace existing rules silently.',
    'Do not apply these rules to unrelated projects or change saved personal criteria.', '',
    '## Practices to try', '', ...persona.rules.map(rule => '- ' + rule), '',
    '## Attribution', '', persona.author + ': ' + persona.source,
    'Adapted from the public article by Avatar. This is not an official persona or the author\'s own AI configuration.',
    '', '## Review later', '',
    'Keep the reason and result of each relevant choice. Review the experiment before making it permanent.', ''].join('\n');
}

from __future__ import annotations

import json
import sqlite3
from pathlib import Path
from typing import Optional

from avatar_common import AvatarError, JsonObject, canonical_json, now
from avatar_projection import criterion_id as projection_criterion_id


def show(
    path: Path, choice_id: Optional[str] = None, criterion_id: Optional[str] = None
) -> JsonObject:
    if store_absent(path):
        if choice_id or criterion_id:
            raise AvatarError("E_NOT_FOUND", "The requested record does not exist.")
        return {"choices": [], "criteria": [], "projections": [], "review_candidates": []}
    connection = connect(path)
    try:
        choices = read_choices(connection, choice_id)
        return {
            "choices": choices,
            "criteria": read_criteria(connection, criterion_id),
            "projections": read_projections(connection),
            "review_candidates": review_candidates(choices),
        }
    finally:
        connection.close()


def check(path: Path, refs: list[str]) -> JsonObject:
    if store_absent(path):
        return {
            "generation": 0,
            "checked_at": now(),
            "results": [unknown_or_scope_mismatch(ref) for ref in refs],
            "store": "absent",
        }
    connection = connect(path)
    try:
        generation = connection.execute(
            "SELECT value FROM meta WHERE key = 'generation'"
        ).fetchone()["value"]
        return {
            "generation": int(generation),
            "checked_at": now(),
            "results": [check_ref(connection, ref) for ref in refs],
        }
    finally:
        connection.close()


def export(path: Path, producer_version: str) -> JsonObject:
    result: JsonObject = {
        "schema": "criteria-snapshot/1",
        "producer": "avatar",
        "producer_version": producer_version,
        "generation": 0,
        "checked_at": now(),
        "scope": {"kind": "personal", "key": "personal"},
        "criteria": [],
        "retired": [],
    }
    if store_absent(path):
        result["store"] = "absent"
        return result
    connection = connect(path)
    try:
        result["generation"] = int(
            connection.execute("SELECT value FROM meta WHERE key = 'generation'").fetchone()["value"]
        )
        for criterion in read_criteria(connection, None):
            current_version = criterion["current_version"]
            for version in criterion["versions"]:
                ref = version["ref"]
                if version["version"] == current_version:
                    if criterion["revoked"]:
                        result["retired"].append({"ref": ref, "status": "revoked"})
                    elif version["confirmation"] == "user_confirmed":
                        result["criteria"].append(version)
                else:
                    result["retired"].append(
                        {
                            "ref": ref,
                            "status": "superseded",
                            "by": f"avatar:{criterion['id']}@{current_version}",
                        }
                    )
        return result
    finally:
        connection.close()


def connect(path: Path) -> sqlite3.Connection:
    connection = sqlite3.connect(path.resolve().as_uri() + "?mode=ro", timeout=30, uri=True)
    connection.row_factory = sqlite3.Row
    connection.execute("PRAGMA busy_timeout = 30000")
    connection.execute("BEGIN")
    return connection


def store_absent(path: Path) -> bool:
    if path.parent.exists() and not path.parent.is_dir():
        raise OSError("Avatar home must be a directory.")
    if path.exists() and not path.is_file():
        raise OSError("Avatar database must be a file.")
    return not path.exists()


def read_choices(
    connection: sqlite3.Connection, choice_id: Optional[str]
) -> list[JsonObject]:
    query = "SELECT id, payload_json, recorded_at FROM choices"
    parameters: tuple[object, ...] = ()
    if choice_id is not None:
        query += " WHERE id = ?"
        parameters = (choice_id,)
    query += " ORDER BY recorded_at, id"
    choices = []
    for row in connection.execute(query, parameters):
        item = json.loads(row["payload_json"])
        item.update({"id": row["id"], "recorded_at": row["recorded_at"]})
        choices.append(item)
    if choice_id is not None and not choices:
        raise AvatarError("E_NOT_FOUND", f"Choice {choice_id} does not exist.")
    return choices


def read_criteria(
    connection: sqlite3.Connection, criterion_id: Optional[str]
) -> list[JsonObject]:
    query = "SELECT id, current_version, revoked FROM criteria"
    parameters: tuple[object, ...] = ()
    if criterion_id is not None:
        query += " WHERE id = ?"
        parameters = (criterion_id,)
    query += " ORDER BY id"
    criteria = []
    for row in connection.execute(query, parameters):
        versions = []
        version_rows = connection.execute(
            "SELECT version, payload_json FROM criterion_versions WHERE id = ? ORDER BY version",
            (row["id"],),
        )
        for version_row in version_rows:
            version = json.loads(version_row["payload_json"])
            version["ref"] = f"avatar:{row['id']}@{version_row['version']}"
            versions.append(version)
        criteria.append(
            {
                "id": row["id"],
                "current_version": int(row["current_version"]),
                "revoked": bool(row["revoked"]),
                "versions": versions,
                "events": read_events(connection, row["id"]),
            }
        )
    if criterion_id is not None and not criteria:
        raise AvatarError("E_NOT_FOUND", f"Criterion {criterion_id} does not exist.")
    return criteria


def read_events(connection: sqlite3.Connection, identifier: str) -> list[JsonObject]:
    events = []
    for row in connection.execute(
        "SELECT * FROM criterion_events WHERE id = ? ORDER BY sequence", (identifier,)
    ):
        event = dict(row)
        event["origin"] = json.loads(event.pop("origin_json"))
        events.append(event)
    return events


def read_projections(connection: sqlite3.Connection) -> list[JsonObject]:
    rows = list(
        connection.execute(
            """SELECT producer, generation, payload_json, fetched_at
               FROM projections ORDER BY producer, generation DESC, fetched_at DESC"""
        )
    )
    highest: dict[str, int] = {}
    for row in rows:
        key = projection_criterion_id(json.loads(row["payload_json"]))
        highest[key] = max(highest.get(key, -1), row["generation"])
    return [
        {
            "producer": row["producer"],
            "generation": int(row["generation"]),
            "fetched_at": row["fetched_at"],
            "current_status_verified": False,
            "newer_projection_exists": row["generation"] < highest[
                projection_criterion_id(json.loads(row["payload_json"]))
            ],
            "history": json.loads(row["payload_json"]),
        }
        for row in rows
    ]


def review_candidates(choices: list[JsonObject]) -> list[JsonObject]:
    result = []
    for index, left in enumerate(choices):
        for right in choices[index + 1 :]:
            shared_refs = sorted(
                set(left.get("source_refs", [])) & set(right.get("source_refs", []))
            )
            if not shared_refs or left.get("chosen") == right.get("chosen"):
                continue
            result.append(
                {
                    "choice_ids": [left["id"], right["id"]],
                    "source_refs": shared_refs,
                    "conditions_differ": canonical_json(
                        left.get("context", {}).get("conditions", [])
                    )
                    != canonical_json(right.get("context", {}).get("conditions", [])),
                }
            )
    return result


def unknown_or_scope_mismatch(ref: str) -> JsonObject:
    status = "scope_mismatch" if not ref.startswith("avatar:") else "unknown"
    return {"ref": ref, "status": status}


def check_ref(connection: sqlite3.Connection, ref: str) -> JsonObject:
    if not ref.startswith("avatar:"):
        return {"ref": ref, "status": "scope_mismatch"}
    try:
        identifier, version_text = ref[len("avatar:") :].rsplit("@", 1)
        version = int(version_text)
    except (ValueError, TypeError):
        return {"ref": ref, "status": "unknown"}
    criterion = connection.execute(
        "SELECT current_version, revoked FROM criteria WHERE id = ?", (identifier,)
    ).fetchone()
    version_row = connection.execute(
        "SELECT payload_json FROM criterion_versions WHERE id = ? AND version = ?",
        (identifier, version),
    ).fetchone()
    if criterion is None or version_row is None:
        return {"ref": ref, "status": "unknown"}
    current_version = int(criterion["current_version"])
    if version != current_version:
        return {
            "ref": ref,
            "status": "superseded",
            "current": f"avatar:{identifier}@{current_version}",
        }
    if criterion["revoked"]:
        return {"ref": ref, "status": "revoked"}
    payload = json.loads(version_row["payload_json"])
    if payload["confirmation"] != "user_confirmed":
        return {"ref": ref, "status": "proposed"}
    return {"ref": ref, "status": "eligible_current"}

