:root { --ink:#292647; --muted:#6d6981; --paper:#fffefb; --lavender:#e9dffc; --mint:#ddf2d5; --yellow:#fff2ac; --peach:#f7ddd2; --line:#e8e5ee; font-family:Pretendard,"Apple SD Gothic Neo","Malgun Gothic",system-ui,sans-serif; color:var(--ink); background:var(--paper); }
